"use client";
import {useEffect,useState} from "react";import {useRouter} from "next/navigation";import {supabase} from "../lib/supabase-browser";
const empty={name:"",price:"",stock:"",category:"",image:"",description:""};const money=n=>`${Number(n||0).toLocaleString("ar-EG")} ج.م`;
export default function Admin(){const db=supabase(),r=useRouter();const [ready,setReady]=useState(false),[orders,setOrders]=useState([]),[products,setProducts]=useState([]),[form,setForm]=useState(empty),[msg,setMsg]=useState(""),[support,setSupport]=useState([]);
useEffect(()=>{(async()=>{const {data:{session}}=await db.auth.getSession();if(!session)return r.replace("/login");const {data:admin}=await db.from("admin_users").select("user_id").eq("user_id",session.user.id).maybeSingle();if(!admin){await db.auth.signOut();return r.replace("/login")}await load();setReady(true)})()},[]);
async function load(){const [o,p,s]=await Promise.all([db.from("orders").select("*").order("created_at",{ascending:false}),db.from("products").select("*").order("created_at",{ascending:false}),db.from("support_messages").select("*").order("created_at",{ascending:false})]);setOrders(o.data||[]);setProducts(p.data||[]);setSupport(s.data||[])}
async function add(e){e.preventDefault();setMsg("");const {error}=await db.from("products").insert({...form,price:Number(form.price),stock:Number(form.stock)});if(error)return setMsg(error.message);setForm(empty);setMsg("تمت إضافة المنتج بنجاح.");load()}
async function remove(id){if(!confirm("حذف المنتج؟"))return;await db.from("products").delete().eq("id",id);load()}
async function change(id,status){await db.from("orders").update({status}).eq("id",id);load()}
async function logout(){await db.auth.signOut();r.replace("/login")}
if(!ready)return <main className="loading">جاري التحقق من الإدارة...</main>;
return <main className="admin-page" dir="rtl"><header className="admin-top"><a href="/">شوبلي <small>SHOPLY ADMIN</small></a><button onClick={logout}>خروج</button></header><section className="admin-wrap"><div className="admin-title"><div><span className="eyebrow">لوحة المتابعة</span><h1>صورة المتجر اليوم</h1><p>الأرقام المهمة، بدون زحمة.</p></div><a className="primary" href="/">عرض المتجر</a></div><div className="stats"><div><span>📦</span><b>{products.length}</b><small>إجمالي المنتجات</small></div><div><span>🧾</span><b>{orders.length}</b><small>كل الطلبات</small></div><div><span>💰</span><b>{money(orders.reduce((s,o)=>s+Number(o.total||0),0))}</b><small>إجمالي المبيعات</small></div></div><section className="admin-card"><h2>إضافة منتج جديد</h2><form className="form-grid" onSubmit={add}>{<><input required placeholder="اسم المنتج" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><input required type="number" min="0" placeholder="السعر بالجنيه" value={form.price} onChange={e=>setForm({...form,price:e.target.value})}/><input required type="number" min="0" placeholder="المخزون" value={form.stock} onChange={e=>setForm({...form,stock:e.target.value})}/><select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}><option value="">اختر القسم</option>{["إلكترونيات","أزياء","المنزل","ألعاب","سيارات","جمال","رياضة","أخرى"].map(x=><option key={x}>{x}</option>)}</select><input className="full-field" placeholder="رابط الصورة (اختياري)" value={form.image} onChange={e=>setForm({...form,image:e.target.value})}/><textarea className="full-field" placeholder="وصف المنتج (اختياري)" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></>}<button className="primary">+ إضافة المنتج</button></form>{msg&&<p className="admin-message">{msg}</p>}</section><section className="admin-card"><div className="card-head"><div><h2>كتالوج المنتجات</h2><p>لا توجد منتجات افتراضية؛ أنت من يضيفها.</p></div></div>{products.length===0?<p className="empty">لا توجد منتجات حاليًا.</p>:<div className="admin-table">{products.map(p=><div className="table-row" key={p.id}><b>{p.name}</b><span>{p.category||"—"}</span><span>{money(p.price)}</span><span>المخزون: {p.stock}</span><button onClick={()=>remove(p.id)}>حذف</button></div>)}</div>}</section><section className="admin-card"><h2>آخر الطلبات</h2>{orders.length===0?<p className="empty">لا توجد طلبات حتى الآن.</p>:orders.map(o=><div className="order-row" key={o.id}><b>#{o.id}</b><span>{o.customer_name} — {o.phone}</span><span>{money(o.total)}</span><select value={o.status} onChange={e=>change(o.id,e.target.value)}><option value="pending">قيد المراجعة</option><option value="confirmed">تم التأكيد</option><option value="preparing">جاري التجهيز</option><option value="shipped">تم الشحن</option><option value="delivered">تم التسليم</option><option value="cancelled">ملغي</option></select></div>)}</section><section className="admin-card"><h2>رسائل الدعم</h2>{support.length===0?<p className="empty">لا توجد رسائل دعم.</p>:support.map(s=><div className="support-row" key={s.id}><b>{s.name||"زائر"}</b><span>{s.phone||"بدون رقم"}</span><p>{s.message}</p></div>)}</section></section></main>}
